package cn.zj.zjmarket.infrastructure.adapter.repository;
import cn.zj.zjmarket.domain.refund.model.Refund;
import cn.zj.zjmarket.domain.refund.model.Refund.Fact;
import cn.zj.zjmarket.infrastructure.gateway.codec.ContractCodec;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;
import javax.sql.DataSource;
import java.util.*;

/** Funds and non-fulfillment evidence, not A's refund acknowledgment, authorize release. */
public final class RefundReleaseRepository {
 private final JdbcTemplate db;private final RefundRepository refunds;private final ObjectMapper json=new ObjectMapper();
 public record Lease(String refundId,String workId,String token,long intentVersion,String eligibilityHash,String successHash){}
 public RefundReleaseRepository(DataSource ds,RefundRepository refunds){db=new JdbcTemplate(ds);this.refunds=refunds;}
 public void validateSchema(){db.queryForList("SELECT check_previous_due_ms FROM b_refund_task LIMIT 0");db.queryForList("SELECT refund_id,proof_hash FROM b_refund_release LIMIT 0");db.queryForList("SELECT operation_id FROM b_refund_operation LIMIT 0");}
 private Map<String,Object> row(String sql,Object...args){var rows=db.queryForList(sql,args);return rows.isEmpty()?null:rows.getFirst();}
 private long now(){return db.queryForObject("SELECT CAST(UNIX_TIMESTAMP(CURRENT_TIMESTAMP(3))*1000 AS SIGNED)",Long.class);}
 private static long num(Map<String,Object> r,String key){return ((Number)r.get(key)).longValue();}
 private static String hash(byte[] b){try{return ContractCodec.sha256(b);}catch(Exception e){throw new IllegalArgumentException(e);}}
 private Map<String,Object> lockTail(Map<String,Object> f){refunds.lockQualification(f);var w=row("SELECT * FROM b_trade_work WHERE kind='REFUND_OBLIGATION' AND business_key=? FOR UPDATE",f.get("payment_id")+":"+f.get("order_id"));db.queryForList("SELECT order_id FROM b_fulfillment WHERE order_id=? FOR UPDATE",f.get("order_id"));db.queryForList("SELECT order_id FROM b_refund_release WHERE order_id=? FOR UPDATE",f.get("order_id"));return w;}
 private void boundWork(Map<String,Object> f,Map<String,Object> w){Refund.require(w!=null&&f.get("order_id").equals(w.get("order_id"))&&f.get("payment_id").equals(w.get("payment_id"))&&f.get("team_id").equals(w.get("team_id"))&&hash((byte[])w.get("evidence")).equals(w.get("evidence_hash")));}
 private void qualify(Map<String,Object> f){refunds.eligible(f,refunds.cursor(f));Refund.require("SUCCEEDED".equals(f.get("funds_status"))&&!"REVIEW_REQUIRED".equals(f.get("sync_status"))&&!"REVIEW_REQUIRED".equals(f.get("release_status")));byte[] raw=(byte[])f.get("success_fact");Refund.require(raw!=null&&hash(raw).equals(f.get("success_hash")));try{var fact=json.readValue(raw,Fact.class);fact.validate(fact.request(),now());Refund.require("SUCCEEDED".equals(fact.status())&&fact.request().refundId().equals(f.get("refund_id"))&&fact.request().orderId().equals(f.get("order_id"))&&fact.request().paymentId().equals(f.get("payment_id"))&&fact.request().amount().equals(f.get("amount").toString())&&fact.request().attemptId().equals(f.get("current_attempt_id"))&&fact.refundedAt()==num(f,"refunded_at_ms")&&refunds.applied(fact));}catch(java.io.IOException e){throw new IllegalArgumentException(e);}}
 public List<String> due(int size){return refunds.releaseDue(size);}
 public Lease claim(String id){Lease[] result={null};refunds.withLocked(id,()->{var f=row("SELECT * FROM b_refund WHERE refund_id=?",id);if(!refunds.scoped(f)||!"SUCCEEDED".equals(f.get("funds_status")))return;refunds.lockQualification(f);var existing=row("SELECT * FROM b_trade_work WHERE kind='REFUND_OBLIGATION' AND business_key=? FOR UPDATE",f.get("payment_id")+":"+f.get("order_id"));if(existing==null){try{qualify(f);}catch(IllegalArgumentException invalid){review(f,null,"RELEASE_PROOF_CONFLICT",now());return;}long created=now();db.update("INSERT INTO b_trade_work(work_id,kind,business_key,order_id,payment_id,team_id,state,evidence,evidence_hash,reasons,created_at_ms,updated_at_ms) VALUES(?,'REFUND_OBLIGATION',?,?,?,?,'DEFERRED_B05',?,?,'[\"RECONCILED_REFUND\"]',?,?) ON DUPLICATE KEY UPDATE work_id=work_id",UUID.randomUUID().toString(),f.get("payment_id")+":"+f.get("order_id"),f.get("order_id"),f.get("payment_id"),f.get("team_id"),f.get("eligibility_proof"),f.get("eligibility_proof_hash"),created,created);}var w=lockTail(f);long n=now();if(w==null||!Set.of("DEFERRED_B05","READY","WAITING_DEPENDENCY","LEASED").contains(w.get("state"))||num(w,"next_attempt_ms")>n||w.get("lease_until_ms")!=null&&num(w,"lease_until_ms")>n)return;
  try{boundWork(f,w);qualify(f);}catch(IllegalArgumentException conflict){review(f,w,"RELEASE_PROOF_CONFLICT",n);return;}String token=UUID.randomUUID().toString();db.update("UPDATE b_trade_work SET state='LEASED',lease_token=?,lease_until_ms=?,updated_at_ms=? WHERE work_id=?",token,n+30000,n,w.get("work_id"));db.update("UPDATE b_refund SET release_status='READY',version=version+1,updated_at_ms=? WHERE refund_id=? AND release_status='HELD'",n,id);result[0]=new Lease(id,w.get("work_id").toString(),token,num(w,"intent_version"),f.get("eligibility_proof_hash").toString(),f.get("success_hash").toString());});return result[0];}
 public boolean complete(Lease lease){boolean[] done={false};refunds.withLocked(lease.refundId(),()->{var f=row("SELECT * FROM b_refund WHERE refund_id=?",lease.refundId());if(!refunds.scoped(f)||!"SUCCEEDED".equals(f.get("funds_status")))return;var w=lockTail(f);long n=now();if(w==null||!"LEASED".equals(w.get("state"))||!lease.workId().equals(w.get("work_id"))||!lease.token().equals(w.get("lease_token"))||lease.intentVersion()!=num(w,"intent_version")||w.get("lease_until_ms")==null||num(w,"lease_until_ms")<=n)return;
  try{boundWork(f,w);Refund.require(lease.eligibilityHash().equals(f.get("eligibility_proof_hash"))&&lease.successHash().equals(f.get("success_hash")));qualify(f);preflight(f);}catch(IllegalArgumentException conflict){review(f,w,"RELEASE_PROOF_CONFLICT",n);return;}apply(f,w,n);done[0]=true;});return done[0];}
 public boolean recover(String id){var l=claim(id);if(l!=null)return complete(l);return replay(id);}
 public boolean replay(String id){boolean[] result={false};refunds.withLocked(id,()->{var f=row("SELECT * FROM b_refund WHERE refund_id=?",id);var w=lockTail(f);var old=row("SELECT * FROM b_refund_release WHERE order_id=?",f.get("order_id"));if(old==null)return;long n=now();try{qualify(f);verifyOld(f,old);result[0]=true;}catch(IllegalArgumentException conflict){review(f,w,"RELEASE_REPLAY_CONFLICT",n);}});return result[0];}
 private void verifyOld(Map<String,Object> f,Map<String,Object> old){Refund.require(f.get("refund_id").equals(old.get("refund_id"))&&f.get("payment_id").equals(old.get("payment_id"))&&f.get("success_hash").equals(old.get("success_hash"))&&f.get("eligibility_proof_hash").equals(old.get("eligibility_hash"))&&num(f,"fact_version")==num(old,"refund_fact_version")&&hash((byte[])old.get("proof")).equals(old.get("proof_hash")));try{var proof=json.readTree((byte[])old.get("proof"));for(var key:Map.of("refundId","refund_id","orderId","order_id","paymentId","payment_id","ledgerId","ledger_id","outcome","outcome","eligibilityHash","eligibility_hash","successHash","success_hash").entrySet())Refund.require(proof.path(key.getKey()).asText().equals(old.get(key.getValue())));Refund.require(proof.path("refundVersion").asLong()==num(old,"refund_fact_version")&&proof.path("releasedAt").asLong()==num(old,"released_at_ms"));}catch(java.io.IOException e){throw new IllegalArgumentException(e);}var ledger=row("SELECT * FROM b_inventory_ledger WHERE ledger_id=?",old.get("ledger_id"));var hold=row("SELECT * FROM b_inventory_reservation WHERE order_id=?",f.get("order_id"));Refund.require(ledger!=null&&"RELEASE".equals(ledger.get("kind"))&&f.get("order_id").equals(ledger.get("order_id"))&&hold!=null&&"RELEASED".equals(hold.get("state")));var order=row("SELECT * FROM b_market_order WHERE order_id=?",f.get("order_id"));Refund.require("CLOSED".equals(order.get("business_status"))&&order.get("goods_id").equals(ledger.get("goods_id"))&&num(ledger,"after_available")==num(ledger,"before_available")+1&&num(ledger,"after_reserved")==num(ledger,"before_reserved")-1&&num(ledger,"after_sold")==num(ledger,"before_sold"));if("ALREADY_RELEASED".equals(old.get("outcome")))unpaidHistory(f,order,hold);if("RELEASED".equals(old.get("outcome")))Refund.require("FULL_REFUND_CONFIRMED".equals(order.get("close_basis"))&&num(order,"closed_at_ms")==num(old,"released_at_ms")&&old.get("proof_hash").equals(order.get("close_evidence_hash"))&&"FULL_REFUND_CONFIRMED".equals(hold.get("resolution_basis"))&&num(hold,"resolved_at_ms")==num(old,"released_at_ms"));}
 private void unpaidHistory(Map<String,Object> f,Map<String,Object> order,Map<String,Object> reservation){String id=f.get("order_id").toString();Refund.require("RELEASED".equals(reservation.get("state"))&&"CLOSED".equals(order.get("business_status"))&&Set.of("LOCAL_NEVER_DISPATCHED","A_CONFIRMED").contains(order.get("close_basis"))&&order.get("closed_at_ms")!=null);var original=db.queryForList("SELECT * FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",id);Refund.require(original.size()==1);Refund.require(order.get("close_evidence")!=null&&order.get("close_evidence_hash")!=null);try{var close=json.readValue(order.get("close_evidence").toString(),cn.zj.zjmarket.domain.order.model.valobj.CloseEvidence.class);Refund.require(hash(json.writeValueAsBytes(close)).equals(order.get("close_evidence_hash"))&&id.equals(close.outTradeNo())&&"CANCELLED".equals(close.orderStatus())&&f.get("team_id").equals(close.teamId()));cn.zj.zjmarket.domain.order.model.valobj.ReservationEvidence.version(close.recordVersion());cn.zj.zjmarket.domain.order.model.valobj.ReservationEvidence.instant(close.closedAt());var request=json.readValue(order.get("close_request").toString(),new com.fasterxml.jackson.core.type.TypeReference<TreeMap<String,Object>>(){});Refund.require(hash(json.writeValueAsBytes(request)).equals(order.get("close_request_hash"))&&id.equals(request.get("outTradeNo"))&&f.get("user_id").equals(request.get("userId"))&&Set.of("NEVER_OPENED","CLOSED_UNPAID").contains(request.get("paymentDisposition")));var a=json.readTree(order.get("a_evidence").toString());Refund.require("CANCELLED".equals(a.path("orderStatus").asText())&&a.path("orderId").asText().equals(close.orderId())&&a.path("source").asText().equals(request.get("source"))&&a.path("channel").asText().equals(request.get("channel")));}catch(Exception e){throw new IllegalArgumentException(e);}}
 private void preflight(Map<String,Object> f){String id=f.get("order_id").toString();var old=row("SELECT * FROM b_refund_release WHERE order_id=?",id);if(old!=null){verifyOld(f,old);return;}var reservation=row("SELECT * FROM b_inventory_reservation WHERE order_id=?",id);var order=row("SELECT * FROM b_market_order WHERE order_id=?",id);Refund.require(reservation!=null);if("HELD".equals(reservation.get("state"))){var account=row("SELECT * FROM b_inventory_account WHERE goods_id=?",order.get("goods_id"));Refund.require(!"CLOSED".equals(order.get("business_status"))&&account!=null&&num(account,"reserved")>0&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,id)==0);}else unpaidHistory(f,order,reservation);}
 private void apply(Map<String,Object> f,Map<String,Object> w,long n){String id=f.get("order_id").toString();var old=row("SELECT * FROM b_refund_release WHERE order_id=?",id);if(old!=null){verifyOld(f,old);finish(f,w,old.get("outcome").toString(),n);return;}var reservation=row("SELECT * FROM b_inventory_reservation WHERE order_id=?",id);var order=row("SELECT * FROM b_market_order WHERE order_id=?",id);Refund.require(reservation!=null);String outcome,ledger;
  if("HELD".equals(reservation.get("state"))){Refund.require(!"CLOSED".equals(order.get("business_status")));var account=row("SELECT * FROM b_inventory_account WHERE goods_id=?",order.get("goods_id"));Refund.require(account!=null&&num(account,"reserved")>0&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,id)==0);ledger=UUID.randomUUID().toString();outcome="RELEASED";db.update("UPDATE b_inventory_account SET available=available+1,reserved=reserved-1,inventory_version=inventory_version+1,updated_at_ms=? WHERE goods_id=?",n,order.get("goods_id"));db.update("INSERT INTO b_inventory_ledger(ledger_id,goods_id,kind,order_id,business_key,delta_available,before_available,after_available,before_reserved,after_reserved,before_sold,after_sold,reason,created_at_ms) VALUES(?,?,'RELEASE',?,?,1,?,?,?,?,?,?,'FULL_REFUND_CONFIRMED',?)",ledger,order.get("goods_id"),id,id,num(account,"available"),num(account,"available")+1,num(account,"reserved"),num(account,"reserved")-1,num(account,"sold"),num(account,"sold"),n);db.update("UPDATE b_inventory_reservation SET state='RELEASED',resolved_at_ms=?,resolution_basis='FULL_REFUND_CONFIRMED' WHERE order_id=?",n,id);
  }else{unpaidHistory(f,order,reservation);ledger=db.queryForObject("SELECT ledger_id FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",String.class,id);outcome="ALREADY_RELEASED";}

  try{var proof=new LinkedHashMap<String,Object>();proof.put("refundId",f.get("refund_id"));proof.put("orderId",id);proof.put("paymentId",f.get("payment_id"));proof.put("refundVersion",f.get("fact_version"));proof.put("successHash",f.get("success_hash"));proof.put("eligibilityHash",f.get("eligibility_proof_hash"));proof.put("ledgerId",ledger);proof.put("outcome",outcome);proof.put("releasedAt",n);byte[] raw=new ContractCodec().encode(proof);db.update("INSERT INTO b_refund_release(order_id,refund_id,payment_id,ledger_id,outcome,refund_fact_version,eligibility_hash,success_hash,proof,proof_hash,released_at_ms) VALUES(?,?,?,?,?,?,?,?,?,?,?)",id,f.get("refund_id"),f.get("payment_id"),ledger,outcome,f.get("fact_version"),f.get("eligibility_proof_hash"),f.get("success_hash"),raw,hash(raw),n);if(outcome.equals("RELEASED")){db.update("UPDATE b_market_order SET business_status='CLOSED',close_basis='FULL_REFUND_CONFIRMED',closed_at_ms=?,close_evidence=?,close_evidence_hash=?,order_version=order_version+1,updated_at_ms=? WHERE order_id=?",n,new String(raw,java.nio.charset.StandardCharsets.UTF_8),hash(raw),n,id);db.update("DELETE FROM b_purchase_guard WHERE active_order_id=?",id);}finish(f,w,outcome,n);}catch(Exception e){throw new IllegalArgumentException(e);}
 }
 private void finish(Map<String,Object> f,Map<String,Object> w,String outcome,long n){db.update("UPDATE b_refund SET release_status=?,release_error=NULL,version=version+1,updated_at_ms=? WHERE refund_id=?",outcome,n,f.get("refund_id"));db.update("UPDATE b_trade_work SET state='DONE',lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",n,w.get("work_id"));}
 private void review(Map<String,Object> f,Map<String,Object> w,String error,long n){db.update("UPDATE b_refund SET release_status='REVIEW_REQUIRED',release_error=?,version=version+1,updated_at_ms=? WHERE refund_id=?",error,n,f.get("refund_id"));if(w!=null)db.update("UPDATE b_trade_work SET state='REVIEW_REQUIRED',intent_version=intent_version+1,lease_token=NULL,lease_until_ms=NULL,updated_at_ms=? WHERE work_id=?",n,w.get("work_id"));}
 public void tick(int size){for(String id:due(size))try{recover(id);}catch(RuntimeException e){System.getLogger(getClass().getName()).log(System.Logger.Level.WARNING,"Refund inventory work retained");}}
}
